/* 英文第二增補 · 潮汐學院原創練習題，非大考中心官方試題。
 * 人物、學校、活動與數據均為原創教學用虛構情境，不代表真實機構或調查。
 * 詞彙與片語既有題數已達目標，本檔補足其餘七單元至各 32 題。
 */

TA.addQuestions('en-gram1', [
  {"id":"en-gram1-y001","d":1,"q":"When I called at noon yesterday, Rita ＿＿＿ lunch and could not answer the phone.","o":["prepares","has prepared","was preparing","will prepare"],"a":2,"e":"昨天中午打電話時，準備午餐的動作正在進行，用過去進行式 was preparing。prepares 是現在習慣，has prepared 是現在完成式，will prepare 指未來，都不符合過去的時間背景。"},
  {"id":"en-gram1-y002","d":1,"q":"Look at those dark clouds. It ＿＿＿ soon.","o":["is going to rain","rained","has rained","was raining"],"a":0,"e":"眼前的烏雲是預測即將下雨的證據，用 is going to rain。其他三項都指已發生或過去正在發生的雨，無法表達 soon 所指的未來。"},
  {"id":"en-gram1-y003","d":2,"q":"By the time the exhibition opens next Friday, the staff ＿＿＿ all the paintings.","o":["had hung","have hanging","will hanging","will have hung"],"a":3,"e":"以未來開展時間為參照，掛畫將在那之前完成，用未來完成式 will have hung。had hung 以過去為參照；have hanging 與 will hanging 都缺少正確的動詞結構。"},
  {"id":"en-gram1-y004","d":1,"q":"If you heat this candle wax enough, it ＿＿＿.","o":["melting","melts","to melt","melt"],"a":1,"e":"此句描述一般條件及結果，it 後需現在式限定動詞 melts。melting 與 to melt 不能單獨作主要動詞，melt 則未配合第三人稱單數主詞。"},
  {"id":"en-gram1-y005","d":2,"q":"I wish I ＿＿＿ the name of the guest standing beside me, but I cannot remember it.","o":["know","knew","will know","have known"],"a":1,"e":"目前想不起名字，wish 後用過去式 knew 表達與現在事實相反的願望。know 與 have known 未表達這種假設，will know 指未來，與眼前的困境不合。"},
  {"id":"en-gram1-y006","d":3,"q":"I wish I ＿＿＿ a copy of that file before my laptop broke yesterday.","o":["save","will save","have saving","had saved"],"a":3,"e":"後悔昨天故障前沒有備份，是對過去的反事實願望，用 wish 加 had saved。save 與 will save 沒有表達過去的遺憾；have saving 本身也不是正確完成式。"},
  {"id":"en-gram1-y007","d":2,"q":"If Maya were here now, she ＿＿＿ us how to adjust the camera.","o":["could show","can showing","had shown","will have shown"],"a":0,"e":"were here now 表示與現在相反的假設，結果用 could 加原形 show。can showing 結構錯誤；had shown 是過去完成式，will have shown 是未來完成式，都不對應此假設。"},
  {"id":"en-gram1-y008","d":3,"q":"＿＿＿ you require further details, please contact the exhibition coordinator.","o":["Had","Were","Should","Would"],"a":2,"e":"Should you require 等於 If you should require，表示日後如有需要。Had 倒裝後需過去分詞，Were 後不能直接接此處的原形 require，Would 也不能這樣代替 if 引導條件。"},
  {"id":"en-gram1-y009","d":2,"q":"Not once during the interview ＿＿＿ the applicant mention her previous salary.","o":["was","had","has","did"],"a":3,"e":"否定片語 Not once 置於句首需倒裝，過去式一般動詞借助 did，後接原形 mention。was 不能接原形動詞；had 與 has 則應接過去分詞 mentioned。"},
  {"id":"en-gram1-y010","d":3,"q":"Only the assistant ＿＿＿ where the spare key is kept; no one else has been told.","o":["do know","know","knows","knowing"],"a":2,"e":"Only 修飾主詞 the assistant，不會觸發倒裝；單數主詞接 knows。do know 與 know 未配合單數主詞，knowing 則不能單獨作限定動詞。"},
  {"id":"en-gram1-y011","d":1,"q":"The students were ＿＿＿ by the ending, which none of them had expected.","o":["surprising","surprised","surprise","surprises"],"a":1,"e":"學生是感到驚訝的人，用 surprised。surprising 表示令人驚訝；surprise 與 surprises 是名詞或動詞形式，不能在此與 were 構成所需的表語。"},
  {"id":"en-gram1-y012","d":2,"q":"＿＿＿ in a protective case, the delicate instrument arrived without damage.","o":["Packed","Packing","Packs","To packing"],"a":0,"e":"instrument 是被裝進保護盒的物品，省略的被動結構需用過去分詞 Packed。Packing 會使儀器成為主動裝箱者；Packs 是限定動詞，To packing 結構也錯誤。"},
  {"id":"en-gram1-y013","d":3,"q":"The rehearsal ＿＿＿ over, the actors began putting away the chairs.","o":["being","was","is","been"],"a":0,"e":"前後主詞不同，且只有逗號連接，前半用獨立分詞構句 The rehearsal being over。was 與 is 會造成逗號錯接，been 不能單獨構成此分詞結構。"},
  {"id":"en-gram1-y014","d":1,"q":"The classroom windows ＿＿＿ every Friday by the cleaning team.","o":["clean","are cleaned","is cleaned","are cleaning"],"a":1,"e":"窗戶是被清潔的，用現在式被動 are cleaned，複數 windows 搭配 are。clean 與 are cleaning 都是主動形式，is cleaned 則主詞動詞不一致。"},
  {"id":"en-gram1-y015","d":2,"q":"You ＿＿＿ bring a printed ticket; showing the digital version is enough.","o":["must not","cannot","need not","had not"],"a":2,"e":"數位票券已足夠，因此沒有必要帶紙本，need not 加原形動詞正好表達「不必」。must not 表示禁止，cannot 表示不能，兩者都不是「沒有必要」；had not 也不能在此直接搭配原形 bring 表達目前的規定。"},
  {"id":"en-gram1-y016","d":2,"q":"When I was a child, my uncle ＿＿＿ take me to the river every summer.","o":["will","has","is","would"],"a":3,"e":"would 可表示過去反覆發生的動作，與童年每年夏天的回憶相符。will 指未來或現在習慣；has 應接過去分詞，is 也不能直接接原形 take。"}
]);

TA.addQuestions('en-gram2', [
  {"id":"en-gram2-y001","d":1,"q":"This is the artist ＿＿＿ sketches we displayed in the hallway.","o":["whom","who","whose","which"],"a":2,"e":"空格修飾 sketches，表示這位藝術家的素描，用所有格 whose。who 與 whom 不能直接表示 sketches 的所有關係，which 也不合此處的人物及所有格結構。"},
  {"id":"en-gram2-y002","d":2,"q":"The colleague to ＿＿＿ I sent the invitation has not replied yet.","o":["whom","who","that","whose"],"a":0,"e":"介系詞 to 後指人的關係代名詞，在正式書面英文中用受格 whom。who 是主格，that 不能直接放在前置介系詞後，whose 是所有格而後面沒有名詞可修飾。"},
  {"id":"en-gram2-y003","d":2,"q":"The microphone stopped working, ＿＿＿ forced us to pause the show.","o":["that","what","where","which"],"a":3,"e":"逗號後用 which 指前面麥克風故障這件事，作 forced 的主詞。that 不用於此非限定關係子句，what 不能這樣接在已完整的前句後，where 也不能作主詞。"},
  {"id":"en-gram2-y004","d":1,"q":"Please tell me ＿＿＿ the nearest bus stop is.","o":["when","where","that","whose"],"a":1,"e":"此處詢問公車站的所在地，用 where 引導間接問句。when 詢問時間，不合此處地點用法；that 後的子句缺少所在地的補語，whose 是所有格，也無法補上地點資訊。"},
  {"id":"en-gram2-y005","d":3,"q":"The committee will choose ＿＿＿ submits the strongest proposal, regardless of age.","o":["whomever","whoever","whatever","whenever"],"a":1,"e":"空格雖位於 choose 的受詞子句內，但本身是 submits 的主詞，應用 whoever。whomever 是受格；whatever 指事物，whenever 指時間，都無法表示提交提案的任何人。"},
  {"id":"en-gram2-y006","d":1,"q":"The room is not large enough ＿＿＿ all the visitors.","o":["holding","held","holds","to hold"],"a":3,"e":"形容詞加 enough 後可接 to V，表示足以做某事，因此用 to hold。holding、held、holds 都不能在此構成 enough 後所需的補語。"},
  {"id":"en-gram2-y007","d":2,"q":"＿＿＿ the limited space, the team managed to build a useful display.","o":["Despite","Although","Because","Unless"],"a":0,"e":"空格後為名詞片語 the limited space，且語意為讓步，用介系詞 Despite。Although、Because、Unless 都需接子句，不能直接接這個名詞片語。"},
  {"id":"en-gram2-y008","d":2,"q":"We will cancel the outdoor workshop ＿＿＿ it rains; otherwise, it will go ahead.","o":["unless","although","if","so that"],"a":2,"e":"下雨是取消的條件，不下雨則照常舉行，用 if。unless 會變成不下雨才取消，although 表讓步，so that 表目的，都與後句條件關係不合。"},
  {"id":"en-gram2-y009","d":3,"q":"I will lend you the original drawing on condition ＿＿＿ you keep it in its folder.","o":["what","which","of","that"],"a":3,"e":"on condition that 是「以……為條件」的固定子句結構。what 與 which 無法接此完整條件子句，of 後不能直接接 you keep 這個限定子句。"},
  {"id":"en-gram2-y010","d":1,"q":"Neither of these two routes ＿＿＿ suitable for wheelchairs because both include stairs.","o":["has being","is be","is","be"],"a":2,"e":"Neither of these two routes 在此作單數主詞，需用限定動詞 is。has being 與 is be 都不是正確動詞結構；be 則不能在這個現在式陳述句中單獨作限定動詞。"},
  {"id":"en-gram2-y011","d":2,"q":"The books on the lower shelf are more suitable for beginners than ＿＿＿ on the upper shelf.","o":["that","those","it","this"],"a":1,"e":"比較兩組不同的書，複數代稱用 those。that、it 與 this 都是單數形式，不能替代前面的複數 books。"},
  {"id":"en-gram2-y012","d":2,"q":"Of the two proposed designs, this one is ＿＿＿.","o":["the more practical","the more practically","the practicalest","as practically"],"a":0,"e":"比較兩個設計時，the more practical 表示其中較實用的一個。practically 是副詞，不能在此當描述設計的形容詞；practical 的比較級為 more practical，不存在 practicalest 這個標準形式。"},
  {"id":"en-gram2-y013","d":3,"q":"The puzzle was ＿＿＿ that even the experienced players needed a hint.","o":["so challenging","such challenging","too challenging","challenging enough"],"a":0,"e":"後面是 that 引導結果子句，需用 so 加形容詞。such 後應有名詞片語，too 與 enough 則不在此直接搭配 that 結果子句。"},
  {"id":"en-gram2-y014","d":1,"q":"The guide asked us ＿＿＿ we had booked the morning tour or the afternoon tour.","o":["that","whether","what","whose"],"a":1,"e":"上午或下午是明確的二選一間接問句，用 whether 搭配 or。that 只引導陳述，what 與 whose 都不能表達此處的選擇關係。"},
  {"id":"en-gram2-y015","d":2,"q":"The sign was too small to read from the entrance. ＿＿＿, we replaced it with a larger one.","o":["Nevertheless","For example","Therefore","Similarly"],"a":2,"e":"告示太小是原因，換成較大的告示是因應結果，用 Therefore。Nevertheless 是讓步，For example 是舉例，Similarly 是類比，都不合此處的因果推進。"},
  {"id":"en-gram2-y016","d":3,"q":"No matter ＿＿＿ carefully we planned, unexpected problems still arose.","o":["what","which","that","how"],"a":3,"e":"No matter how 加副詞 carefully 表示無論規劃得多仔細。what、which 不能修飾 carefully 表程度，that 也不能完成 no matter 的讓步結構。"}
]);

TA.addQuestions('en-cloze', [
  {"id":"en-cloze-y001","d":1,"q":"Which expression best completes blank (1)?","o":["therefore","for instance","however","likewise"],"a":2,"e":"原以為演技好就足夠，第一份錄音卻充滿雜音，用 however 表轉折。therefore 表結果，for instance 表舉例，likewise 表相同情況，都不合預期與實際的落差。","pid":"yp1","passages":{"yp1":"When our drama club began recording an audio play, we assumed that good acting would be enough. Our first recording, ＿＿＿(1), was full of distracting noises. Chairs scraped across the floor, and someone opened a snack bag during an important speech.<br><br>To solve the problem, we gave one member the ＿＿＿(2) of listening for unwanted sounds. We also placed a sign outside the room, ＿＿＿(3) everyone to keep quiet. After each scene, we listened together and decided what needed to change. At first, some actors felt embarrassed ＿＿＿(4) hearing their own voices. Gradually, they began to treat the recordings as useful feedback rather than personal criticism. The final play was not perfect, but the process taught us that quality depends on careful listening as well as ＿＿＿(5)."}},
  {"id":"en-cloze-y002","d":1,"q":"Which word best completes blank (2)?","o":["responsibility","permission","decoration","temperature"],"a":0,"e":"分派一位成員聽取雜音，是給他一項 responsibility「職責」。permission 是許可，並非此處的任務分工；decoration 與 temperature 更與錄音工作無關。","pid":"yp1"},
  {"id":"en-cloze-y003","d":2,"q":"Which form best completes blank (3)?","o":["reminded","reminds","to reminding","reminding"],"a":3,"e":"逗號後用 reminding 補充張貼告示帶來的提醒作用。reminded 表被動或過去式，不合此結構；reminds 是未連接的限定動詞，to reminding 也不合文法。","pid":"yp1"},
  {"id":"en-cloze-y004","d":2,"q":"Which word best completes blank (4)?","o":["to","about","of","from"],"a":1,"e":"feel embarrassed about 加事件表示對某事感到尷尬，此處是聽見自己的聲音。to hearing、of hearing 與 from hearing 都不合此處表達尷尬原因的標準搭配。","pid":"yp1"},
  {"id":"en-cloze-y005","d":3,"q":"Which word best completes blank (5)?","o":["performed","performing","performs","perform"],"a":1,"e":"as well as 連接平行成分，前面是動名詞 listening，後面應用 performing。performed、performs 與 perform 都不能與此處的 listening 構成所需的動名詞對稱。","pid":"yp1"},
  {"id":"en-cloze-y006","d":1,"q":"Which word best completes blank (1)?","o":["accidentally","silently","previously","differently"],"a":3,"e":"大家視木板為垃圾，老師卻看出可做標牌，用 differently 表不同的看法。accidentally 是偶然地，silently 是安靜地，previously 是先前，都不能表達這種觀點差異。","pid":"yp2","passages":{"yp2":"After our school replaced several classroom doors, a pile of wooden panels remained in a storage room. Most people regarded them as rubbish. Our art teacher saw them ＿＿＿(1): they could become signs for the school garden.<br><br>Before painting, we checked every panel for sharp edges. Any piece that could not be made safe was ＿＿＿(2) from the project. We then asked the gardening club which plants needed labels. ＿＿＿(3) guessing the names, we checked the club's planting list and asked its members to confirm them. The finished signs were colorful, but their greatest value was practical. They helped visitors identify the plants ＿＿＿(4) having to ask a club member each time."}},
  {"id":"en-cloze-y007","d":2,"q":"Which word best completes blank (2)?","o":["excluded","borrowed","rescued","copied"],"a":0,"e":"無法處理到安全的木板應從計畫中 excluded「排除」。borrowed 是借入，rescued 是救出，copied 是複製，都不合安全篩選的目的。","pid":"yp2"},
  {"id":"en-cloze-y008","d":2,"q":"Which expression best completes blank (3)?","o":["As a result of","In addition to","Instead of","For the sake of"],"a":2,"e":"他們查名單並請社員確認，以取代猜測，用 Instead of。As a result of 表原因，In addition to 表兩者都做，For the sake of 表目的，均不合避免猜測的行動。","pid":"yp2"},
  {"id":"en-cloze-y009","d":3,"q":"Which word best completes blank (4)?","o":["despite","by","after","without"],"a":3,"e":"標牌讓訪客不用每次詢問就能辨認植物，用 without 加 having。despite 表儘管，by 表藉由，after 表之後，都無法表達標牌省去詢問的作用。","pid":"yp2"},
  {"id":"en-cloze-y010","d":1,"q":"Which word best completes blank (1)?","o":["expensive","obedient","sufficient","edible"],"a":2,"e":"兩人記得不同位置，表示單靠記憶不足以釐清，用 sufficient「足夠的」。expensive 指昂貴，obedient 指服從，edible 指可食，都不合證據是否足夠的語境。","pid":"yp3","passages":{"yp3":"During a class project, we interviewed neighbors about places they remembered from childhood. We soon discovered that memory alone was not always ＿＿＿(1). Two people gave different locations for the same old bakery.<br><br>Rather than deciding that one person must be lying, we looked for other evidence. An old photograph showed the bakery beside a bridge, ＿＿＿(2) helped us understand the disagreement. The shop had moved after the bridge was rebuilt. Both speakers had remembered it correctly, but at different times.<br><br>We added dates to our map ＿＿＿(3) readers could distinguish the two locations. The experience reminded us to investigate apparent contradictions before ＿＿＿(4) a conclusion."}},
  {"id":"en-cloze-y011","d":2,"q":"Which word best completes blank (2)?","o":["that","which","what","when"],"a":1,"e":"逗號後 which 指照片所呈現的資訊，作 helped 的主詞。that 不可用於此非限定關係子句；what 不能這樣接前句，when 則無法作 helped 的主詞。","pid":"yp3"},
  {"id":"en-cloze-y012","d":2,"q":"Which expression best completes blank (3)?","o":["so that","even though","as if","now that"],"a":0,"e":"加上日期的目的是讓讀者分辨不同位置，用 so that 引導目的子句。even though 是讓步，as if 是彷彿，now that 是既然，都不合目的關係。","pid":"yp3"},
  {"id":"en-cloze-y013","d":3,"q":"Which word best completes blank (4)?","o":["drawing","painting","pulling","designing"],"a":0,"e":"draw a conclusion 是「下結論」的固定搭配，before 後可接動名詞 drawing。painting、pulling 與 designing 雖也為動名詞，但不與 conclusion 搭配成此意思。","pid":"yp3"},
  {"id":"en-cloze-y014","d":1,"q":"Which word best completes blank (1)?","o":["reward","barrier","ceiling","forecast"],"a":1,"e":"害怕作品不夠好阻止投稿，是一道 barrier「障礙」，簡短提案表能降低它。reward 是獎勵，ceiling 在此不是心理障礙，forecast 是預測，都不合投稿困難的語意。","pid":"yp4","passages":{"yp4":"Our student magazine once accepted articles only as complete drafts. This seemed efficient, but several students said they never submitted anything because they were afraid their writing was not good enough. To lower this ＿＿＿(1), the editors introduced a short idea form.<br><br>Now a student can propose a topic and explain why it matters before writing a full article. If an idea is accepted, an editor helps the student make an outline. Students still write their own work; the editor's role is to offer ＿＿＿(2), not to replace their voices.<br><br>The new process takes more discussion at the beginning. ＿＿＿(3), it gives writers a clearer direction and reduces unnecessary rewriting later. Students who ＿＿＿(4) silent before the change are now willing to share their ideas."}},
  {"id":"en-cloze-y015","d":2,"q":"Which word best completes blank (2)?","o":["ownership","punishment","guidance","silence"],"a":2,"e":"編輯協助提綱並保留作者聲音，是提供 guidance「指導」。ownership 是所有權，punishment 是處罰，silence 是沉默，都不是這項協助的內容。","pid":"yp4"},
  {"id":"en-cloze-y016","d":2,"q":"Which expression best completes blank (3)?","o":["In other words","For instance","In the same way","Nevertheless"],"a":3,"e":"前句承認一開始討論較多，後句提出仍有方向清楚等好處，用 Nevertheless 表讓步轉折。In other words 是換句話說，For instance 是舉例，In the same way 是類比，都無法表達此處承認代價後再提出好處的關係。","pid":"yp4"},
  {"id":"en-cloze-y017","d":3,"q":"Which form best completes blank (4)?","o":["have remaining","will remain","had remained","are remained"],"a":2,"e":"before the change 指過去改革以前持續沉默的狀態，用過去完成式 had remained。have remaining 不是正確完成式，will remain 指未來；remain 在此不及物，不能用 are remained 被動式。","pid":"yp4"}
]);

TA.addQuestions('en-struct', [
  {"id":"en-struct-y001","d":1,"q":"Which sentence best completes blank (1)?","o":["A quieter location was clearly needed.","The team decided that clear sound did not matter.","None of the students wanted to speak to anyone.","The hallway was completely empty during the test."],"a":0,"e":"前句說走廊談話干擾收音，後句移至空教室，中間應提出需要更安靜的地點。其他選項否定收音的重要性、臆測學生意願，或與走廊有人談話矛盾。","pid":"yp1","passages":{"yp1":"A student team planned to record interviews in a busy school hallway. During a test, passing conversations made the speakers hard to hear. ＿＿＿(1) The team moved the recording session to an unused classroom and put a notice on the door.<br><br>Before each interview, a team member explained who would hear the recording and asked the speaker for permission. ＿＿＿(2) Anyone who refused could still help by sharing written notes.<br><br>Afterward, the team sent each speaker a copy of the planned quotation. ＿＿＿(3) One speaker noticed that a sentence had been cut in a way that changed its meaning, so the team restored the missing words.<br><br>The project required more steps than simply pressing a record button. ＿＿＿(4) The final report represented the speakers' views more faithfully because of that extra care."}},
  {"id":"en-struct-y002","d":2,"q":"Which sentence best completes blank (2)?","o":["Written notes were forbidden in the project.","Every participant had to be recorded, even if they preferred to provide written notes.","Permission was requested only after publication.","Participation was a choice, not a requirement."],"a":3,"e":"前文先徵求同意，後文允許拒絕者改提供筆記，可知參與錄音是自願。其他選項分別禁止筆記、強迫同意或延後徵求許可，都與前後文明確資訊相反。","pid":"yp1"},
  {"id":"en-struct-y003","d":2,"q":"Which sentence best completes blank (3)?","o":["They were asked to choose the color of the classroom door.","The speakers could check the accuracy of their quotations.","The quotations were never shown to the speakers.","This ensured that no quotation could ever contain an error."],"a":1,"e":"受訪者能核對預計刊出的引文是否正確傳達原意，後句正好舉出修正刪節錯誤的例子。門的顏色離題；從未展示引文與前句矛盾；校閱能發現錯誤，但不能保證引文永遠不會出錯。","pid":"yp1"},
  {"id":"en-struct-y004","d":3,"q":"Which sentence best completes blank (4)?","o":["Those steps mainly trained speakers to give longer speeches.","Those steps helped protect both the speakers and the meaning of their words.","Those steps made every interview follow the same story.","Those steps replaced the speakers' approval with the team's judgment."],"a":1,"e":"Those steps 統整徵求同意與核對引文，既保護受訪者，也保留原意，銜接末句更忠實的報告。前文並非訓練長篇演說或統一故事內容，也不是以團隊判斷取代受訪者核准。","pid":"yp1"},
  {"id":"en-struct-y005","d":1,"q":"Which sentence best completes blank (1)?","o":["The jackets were all thrown away immediately.","The boxes already had clear lists on their fronts.","We decided never to use costumes again.","The boxes needed a way to show what was inside."],"a":3,"e":"找衣服需要逐箱打開，故需要外部標示內容，接著才寫大標籤。已有清楚清單與困境矛盾，丟掉衣服及不用戲服則接不上後續整理。","pid":"yp2","passages":{"yp2":"At first, our class kept all the costumes for the school play in identical boxes. Finding one jacket meant opening almost every box. ＿＿＿(1) We wrote the contents on large labels and placed them on the front of each box.<br><br>The labels helped, but costumes were still sometimes returned to the wrong place. ＿＿＿(2) After that, each actor could compare the costume with the image before putting it away.<br><br>We also left one box for items that needed repair. ＿＿＿(3) A volunteer checked that box after each rehearsal and fixed what she could.<br><br>These changes did not require expensive equipment. ＿＿＿(4) By making the storage system easier to understand, we reduced confusion before performances."}},
  {"id":"en-struct-y006","d":2,"q":"Which sentence best completes blank (2)?","o":["Each label now showed a photo of the contents.","All the labels were removed without replacement.","The actors were told to hide the costumes at home.","No photographs were taken at any stage."],"a":0,"e":"後句的 the image 需要前面引出照片，照片也能解決放錯箱的問題。移除標籤、藏在家裡都破壞整理目的，沒有拍照更使 image 失去指涉。","pid":"yp2"},
  {"id":"en-struct-y007","d":2,"q":"Which sentence best completes blank (3)?","o":["The repair box was reserved for perfectly clean scripts.","All damaged items had to stay in the main costume boxes.","Damaged costumes went there, away from usable ones.","Nothing was ever allowed inside the repair box."],"a":2,"e":"there 指維修箱，放破損戲服才能讓志工下一句檢查與修補。劇本離題，受損物留在一般箱及維修箱不能放物，都與專設維修箱的目的矛盾。","pid":"yp2"},
  {"id":"en-struct-y008","d":3,"q":"Which sentence best completes blank (4)?","o":["Their value lay chiefly in increasing the number of costumes the class owned.","Their purpose was to make every actor repair all the costumes.","Their success came from eliminating choices about costume design.","Their value came from clearer information rather than a bigger budget."],"a":3,"e":"前句說不需昂貴設備，末句說易理解而減少混亂，重點在資訊清楚。整理並未增加戲服數量，修補由志工負責，也沒有消除戲服設計的選擇。","pid":"yp2"},
  {"id":"en-struct-y009","d":1,"q":"Which sentence best completes blank (1)?","o":["The photograph listed every registration rule in words.","Families had already received complete written instructions.","It looked attractive but left important questions unanswered.","The organizers had decided to cancel the event."],"a":2,"e":"只有標題與照片無法提供時間及報名資訊，因此留下重要問題。照片提供全部規則、已收到完整指示都無法解釋後句困惑；取消活動也與全文不合。","pid":"yp3","passages":{"yp3":"Our school website announced a weekend science event. The first version of the announcement included only the event title and a cheerful photograph. ＿＿＿(1) Some families did not know when to arrive or whether they needed to register.<br><br>The organizers revised the page with a short list of practical details. ＿＿＿(2) The new version also explained that the event was free but that registration was required.<br><br>A parent then asked whether the experiments were suitable for very young children. ＿＿＿(3) The organizers added a note recommending the activities for children aged eight and above.<br><br>Finally, they asked someone who had not helped plan the event to read the page. ＿＿＿(4) Her questions revealed another missing detail: where visitors should enter the building."}},
  {"id":"en-struct-y010","d":1,"q":"Which sentence best completes blank (2)?","o":["These included only a second photograph.","These included the date, starting time, and location.","No information about the schedule was added.","The organizers removed all practical information."],"a":1,"e":"These 指前句的實用資訊，日期、時間與地點正好回應家庭疑問。其餘選項只加照片、沒有時程或刪除資訊，都與 revised with a short list 不合。","pid":"yp3"},
  {"id":"en-struct-y011","d":2,"q":"Which sentence best completes blank (3)?","o":["That question showed that age guidance was needed as well.","The parent asked to design the photograph for the event.","The organizers said that age could never matter.","The answer was to remove all descriptions of the activities."],"a":0,"e":"家長詢問幼兒是否適合，促使主辦方補建議年齡，銜接需有年齡資訊最合理。設計照片離題，年齡不重要與後句矛盾，移除活動描述也無法回應問題。","pid":"yp3"},
  {"id":"en-struct-y012","d":3,"q":"Which sentence best completes blank (4)?","o":["A fresh reader could notice gaps that the organizers had overlooked.","Her role was to confirm that every experiment was scientifically original.","She was asked to rank the activities by their material costs.","Her task was to replace the written details with a more cheerful photograph."],"a":0,"e":"未參與規劃的讀者能找出主辦方忽略的資訊缺口，後句入口問題即為例證。此處是在檢查公告是否清楚，並非審查實驗原創性、比較材料成本，或以照片取代已補上的資訊。","pid":"yp3"},
  {"id":"en-struct-y013","d":1,"q":"Which sentence best completes blank (1)?","o":["Every family agreed to throw away its original photographs.","Protecting those originals was therefore a priority.","The display required the originals to be left outdoors in the rain.","Copies were forbidden because all images were identical."],"a":1,"e":"唯一副本珍貴，所以下句掃描後先歸還原件，保護原件是合理銜接。丟棄、淋雨或禁止副本都與謹慎保存的行動相反。","pid":"yp4","passages":{"yp4":"A neighborhood group planned a wall display of old photographs. The photographs belonged to several families, and some were the only copies they had. ＿＿＿(1) The group scanned the originals and returned them before preparing the display.<br><br>Each digital image needed a caption. ＿＿＿(2) When a date was uncertain, the group wrote \"around\" before the year rather than presenting a guess as an exact fact.<br><br>One photograph showed a small shop beside a wide road. ＿＿＿(3) An older resident identified it and explained that the road had once been much narrower.<br><br>The completed display was more than a collection of attractive images. ＿＿＿(4) Visitors could learn what the pictures showed and how confidently each detail was known."}},
  {"id":"en-struct-y014","d":2,"q":"Which sentence best completes blank (2)?","o":["The captions contained only random numbers.","No one was asked about the photographs.","They asked owners for names, places, and rough dates.","The owners had to invent an exact year for every image."],"a":2,"e":"caption 需要人物、地點及日期資訊，並銜接日期不確定時用 around。隨機數字無法說明照片，未詢問與取得資訊不合，要求捏造確切年份則與標明不確定性相反。","pid":"yp4"},
  {"id":"en-struct-y015","d":2,"q":"Which sentence best completes blank (3)?","o":["Everyone in the planning team immediately named the shop correctly.","The shop was invisible in the photograph.","No resident was ever shown the image.","At first, no one in the planning team recognized the building."],"a":3,"e":"先不認得建築，再由年長居民辨認，敘事自然推進。全員已認得則無需這段辨認轉折；看不到店與照片描述矛盾，居民未看圖也與下一句相反。","pid":"yp4"},
  {"id":"en-struct-y016","d":3,"q":"Which sentence best completes blank (4)?","o":["Its captions turned every approximate date into an exact date.","The images made residents' explanations unnecessary.","Its captions linked stories to images and noted uncertainty.","Its value depended on visitors already knowing every building."],"a":2,"e":"說明文字將照片連結到地方故事，也以 around 保留不確定性，銜接末句知道各資訊可信程度。沒有將約略日期改成確切日期；居民解說正是資料來源，訪客也不需先認得建築才能學到內容。","pid":"yp4"},
  {"id":"en-struct-y017","d":1,"q":"Which sentence best completes blank (1)?","o":["A basic condition standard was needed.","Missing pages made the books easier to read.","The class decided to accept only empty notebooks.","All books had been carefully checked before donation."],"a":0,"e":"缺頁問題促使訂定書況標準，後句要求完整可讀正好承接。缺頁更好讀不合理，只收筆記本離題，早已查驗則與首週問題不合。","pid":"yp5","passages":{"yp5":"Our class exchange shelf allows students to leave books they no longer need and take books they want to read. During the first week, some students left books with missing pages. ＿＿＿(1) We agreed that donated books must be complete and readable.<br><br>We then faced a different problem: the shelf filled up with the same few titles. ＿＿＿(2) Students could write down a title they hoped to find, helping donors decide what to bring.<br><br>No one was required to donate a book before taking one. ＿＿＿(3) A student with no spare books could still use the shelf.<br><br>Once a month, volunteers checked for damaged items and updated the request list. ＿＿＿(4) The shelf remained useful because someone regularly cared for it."}},
  {"id":"en-struct-y018","d":2,"q":"Which sentence best completes blank (2)?","o":["We therefore required every donor to bring exactly the same title.","The shelf was permanently closed that day.","We removed every way for readers to share their interests.","To make the collection more varied, we added a request list."],"a":3,"e":"同樣書名太多，需求清單可引導不同捐贈，後句 Students could write down 呼應 request list。要求同一本會惡化問題，永久關閉及移除表達管道都接不上後文。","pid":"yp5"},
  {"id":"en-struct-y019","d":3,"q":"Which sentence best completes blank (3)?","o":["Readers were rewarded in proportion to the number of books they donated.","Students could take books even if they had none to donate.","Donations functioned as admission tickets to the shelf.","The shelf served only students who already owned large collections."],"a":1,"e":"不用先捐書，無餘書者也可取書，說明資格不取決於回報能力。按捐贈量分配取書、把捐贈當入場券或僅服務藏書多者，都與前後文的開放規則不合。","pid":"yp5"},
  {"id":"en-struct-y020","d":2,"q":"Which sentence best completes blank (4)?","o":["The monthly checks were never carried out.","This kept the books and request list useful.","The request list stayed untouched forever.","Damaged items became the only books available."],"a":1,"e":"This 指每月檢查受損書及更新需求清單的做法，這些工作使書籍與清單保持可用，銜接末句持續照顧書架。從未檢查、永不更新及只剩壞書，都否定前句明述的維護措施。","pid":"yp5"}
]);

TA.addQuestions('en-read', [
  {"id":"en-read-y001","d":1,"q":"What was the online exhibition mainly about?","o":["The history of school uniforms","Methods of photographing shadows","Lena's favorite outdoor sports","Changes to the school grounds"],"a":3,"e":"第二段明說展覽主題是 changes to the school grounds。制服、攝影陰影與個人運動喜好都不是展覽主題，不能因第一段出現 clothing 或 shadows 就選它們。","pid":"yp1","passages":{"yp1":"When Lena volunteered to describe the photographs in her school's online exhibition, she began by listing everything she could see. A picture of the school entrance received a long description of bricks, windows, trees, shadows, and students' clothing. Her partner, Theo, asked a simple question: \"What does a visitor need to understand about this picture?\"<br><br>The exhibition was about changes to the school grounds. In this section, the photograph illustrated a new entrance ramp. Lena's description buried that detail among dozens of less relevant observations. She rewrote it to explain the ramp's location and its connection to the main doorway. She kept a brief description of the building, but removed details that did not help readers understand the change.<br><br>For a later section on student life, she described a photograph differently. The students' actions mattered there because the image showed how they used a shared outdoor space. Theo reminded her that useful descriptions depend on why an image is included, not simply on how many objects it contains.<br><br>The pair tested their descriptions with classmates who had not seen the photographs. When a reader imagined the ramp on the wrong side of the building, Lena revised the wording. She learned that writing a description was not a matter of recording every visible detail. It was a matter of choosing relevant information and checking whether the words conveyed it clearly."}},
  {"id":"en-read-y002","d":2,"q":"Why did Lena rewrite the description of the entrance photograph?","o":["It buried the new ramp among less relevant details.","The ramp had been removed after the photograph was taken.","Theo wanted all descriptions to contain the same number of words.","The photograph showed no part of the school building."],"a":0,"e":"照片為說明新坡道而放入，原描述卻讓此重點淹沒在細節中，因此需改寫。文章未說坡道拆除或統一字數，照片也明確有校舍。","pid":"yp1"},
  {"id":"en-read-y003","d":2,"q":"In the second paragraph, \"buried\" is closest in meaning to ＿＿＿.","o":["placed under the ground","proved to be incorrect","made difficult to notice","repeated at the beginning"],"a":2,"e":"buried that detail among observations 是比喻重點被許多觀察掩蓋，不易注意。不是實際埋入土中，也不是證明錯誤或重複置於開頭。","pid":"yp1"},
  {"id":"en-read-y004","d":3,"q":"Which principle would Lena most likely apply to another exhibition image?","o":["Include every visible object so that no selection is necessary.","Remove descriptions whenever readers initially misunderstand them.","Use one fixed description for every photograph of the same location.","Choose details for the purpose, then revise using reader feedback."],"a":3,"e":"全文包含按展覽用途選細節及測試後改寫，正解統整兩個步驟。列出全部細節正是原本問題，誤解後應修訂而非移除，同地點也可能因用途不同而需不同描述。","pid":"yp1"},
  {"id":"en-read-y005","d":1,"q":"What prevented Amir's mother from attending the original selection meeting?","o":["A lack of interest in storytelling","A rule against shop owners","Her work schedule","The absence of a neighborhood connection"],"a":2,"e":"第二段說母親在會議時要工作，故是工時衝突。她後來分享開店故事，顯示有興趣且有地方連結；文中也沒有禁止店主參加。","pid":"yp2","passages":{"yp2":"The organizers of a neighborhood storytelling evening originally planned to select speakers through a single open meeting. Anyone interested would give a short speech, and the audience would vote. The procedure seemed fair because everyone received the same amount of speaking time.<br><br>Then Amir pointed out a difficulty. His mother worked during the meeting, while another interested neighbor cared for a family member and could not attend. Neither person lacked a story; both lacked a way to enter the selection process. The organizers decided to accept written proposals and voice recordings as well as live speeches. They published the same selection criteria for all three formats: a clear connection to the neighborhood, a focused story, and respect for the people mentioned.<br><br>The change did not mean every applicant would become a speaker. The program still had limited space, and proposals would still be evaluated. However, attendance at one particular meeting was no longer a condition for consideration. The organizers also offered help with recording to people who needed it.<br><br>At the event, Amir's mother told a story about opening her first shop. The organizers did not claim that they had removed every possible obstacle. Instead, they said they would ask participants what had made applying difficult and use those comments to improve the next event."}},
  {"id":"en-read-y006","d":2,"q":"Which statement accurately describes the revised application process?","o":["Applicants had to attend the open meeting.","Applicants were evaluated according to shared criteria.","Every proposal was guaranteed a place in the program.","Only live speeches could be submitted."],"a":1,"e":"改革後三種提交方式適用同一套公布標準，也仍需評選。出席不再必要，名額有限且非人人入選，現場演說也不再是唯一方式。","pid":"yp2"},
  {"id":"en-read-y007","d":3,"q":"What does the passage suggest about the original procedure?","o":["Equal speaking time did not give everyone an equal chance to enter the process.","Equal speaking time guaranteed that all interested neighbors could participate.","Voting was rejected because it always produces unfair results.","People unable to attend were less likely to have useful stories."],"a":0,"e":"原本時間相等，卻有人無法出席，因此進入評選的機會仍不平等。其餘選項誤把時間平等當全面公平、無據批判所有投票，或把不能出席誤解成故事較差。","pid":"yp2"},
  {"id":"en-read-y008","d":2,"q":"How do the organizers view the revised process at the end?","o":["As an improvement that can still be developed further","As proof that every obstacle has disappeared","As a reason to stop collecting feedback","As a temporary change that must be reversed immediately"],"a":0,"e":"末段明說未排除所有障礙，將收集意見改善下次活動，故視為可再進步的改良。完全無障礙、停止回饋及立即撤回都與其態度相反。","pid":"yp2"},
  {"id":"en-read-y009","d":1,"q":"What did the students count during the first comparison?","o":["All the trays returned each week","Trays placed on the wrong shelf","The number of signs in the school","Classes that ate outside the lunchroom"],"a":1,"e":"第一段說計算放錯架的次數，第二段特別說未計算總歸還量。告示數量未測，外食班級是在事後查時程才發現的，並非原本計數項目。","pid":"yp3","passages":{"yp3":"A school team wanted to learn whether a new sign made the lunchroom's tray-return area easier to use. For one week, a student observer counted how often people placed trays on the wrong shelf. The team then installed a sign with short instructions and repeated the count for another week. Fewer misplaced trays were recorded after the sign appeared.<br><br>Some team members wanted to announce that the sign had solved the problem. Their teacher asked what else had changed between the two weeks. The students checked the lunchroom schedule and discovered that several classes had eaten elsewhere during the second week. They had recorded the number of misplaced trays, but not the total number of trays returned. A lower count could therefore partly reflect fewer users.<br><br>The team planned another comparison. This time, it would record both total returns and mistakes, and note unusual changes in the schedule. It would also ask users whether the sign was easy to understand. The teacher explained that a helpful comment from a user and a change in the mistake rate answered different questions; both could be useful, but one should not be treated as the other.<br><br>The students kept the sign because it was inexpensive and users said the instructions were clear. Yet they revised their report. Rather than declaring the sign a proven success, they described the first result as encouraging evidence that needed a more careful check."}},
  {"id":"en-read-y010","d":2,"q":"Why could the lower number of mistakes be misleading?","o":["The students counted every correct return as a mistake.","The sign had been removed before the second week began.","Fewer users may have returned trays in the second week.","All lunchroom users refused to follow instructions."],"a":2,"e":"第二週有幾班改在別處用餐，較少錯誤可能部分來自較少使用者。把正確當錯誤、移除告示及全員拒絕遵守都不是文中原因。","pid":"yp3"},
  {"id":"en-read-y011","d":1,"q":"What would the team add to its next comparison?","o":["The price of every lunch","The names of all students making mistakes","The length of each school lesson","The total number of trays returned"],"a":3,"e":"第三段說下次同時記錄總歸還量與錯誤量。午餐價格、犯錯者姓名及課堂長度都不在改進計畫中。","pid":"yp3"},
  {"id":"en-read-y012","d":2,"q":"What is the teacher's point about user comments and mistake rates?","o":["Positive comments prove that the mistake rate has fallen.","Mistake rates can be measured without recording any counts.","They answer different questions and are not interchangeable.","User comments should never be collected in a school project."],"a":2,"e":"老師說兩者回答不同問題，雖皆有用卻不能互相替代。好評不能直接證明錯誤率下降，錯誤率仍需計數資料，也不是應完全禁止收集意見。","pid":"yp3"},
  {"id":"en-read-y013","d":3,"q":"Which sentence would best fit the students' revised report?","o":["The decrease is promising, but the sign's effect remains unproven.","The sign has eliminated all tray-return mistakes permanently.","The decrease proves that every lunchroom user read the sign.","The sign must be useless because the first comparison was imperfect."],"a":0,"e":"末段保留告示並承認初步結果待確認，正解兼顧潛力與因果證據限制。永久消除及全員讀過都是過度推論；研究不足也不等於告示必然無效。","pid":"yp3"}
]);

TA.addQuestions('en-mixed', [
  {"id":"en-mixed-y001","d":1,"q":"Who can play without an accompanying adult?","o":["A fifteen-year-old with a reservation","An eleven-year-old accompanied by a parent","A thirteen-year-old spectator with no reservation","A sixteen-year-old with a reservation"],"a":3,"e":"滿十六歲且已預約可獨自參賽。十五歲仍需成人陪同，十一歲未達最低年齡，十三歲無預約者只能旁觀，不能因此取得玩家資格。","pid":"yp1","passages":{"yp1":"<b>Meadow Community Center: Board Game Afternoon</b><br>Saturday, 2:00–4:30 p.m.; check-in begins at 1:40 p.m.<br>Admission is free, but every player needs a reservation. Spectators do not need reservations.<br>Players must be at least twelve years old. Players aged twelve to fifteen must attend with an adult. Players aged sixteen or above may attend alone.<br>Games and pencils are provided. Bring your own water bottle. Food is not allowed in the game room.<br>Reservations open on Tuesday at 6:00 p.m. and close when all places are filled. An unclaimed player place will be released at 2:10 p.m.<br>If you cannot attend, cancel through the booking page so someone else can use your place."}},
  {"id":"en-mixed-y002","d":2,"q":"Which plan fully follows the notice?","o":["A fourteen-year-old reserves a place and attends alone.","A fourteen-year-old reserves a player place and attends with her father.","A seventeen-year-old arrives without a reservation and demands a player place.","A parent brings an eleven-year-old to play because adults can waive the age limit."],"a":1,"e":"十四歲有預約並由父親陪同，符合全部條件。未滿十六歲不可獨自參賽，年滿十六歲仍需預約，成人陪同也不能免除最低年齡限制。","pid":"yp1"},
  {"id":"en-mixed-y003","d":1,"q":"What should a player bring?","o":["A board game","A water bottle","A pencil","Food for the game room"],"a":1,"e":"公告要求自備水瓶，遊戲與鉛筆會提供，遊戲室更禁止食物。不能把會提供的用品或明令禁止的物品當作必須攜帶的物品。","pid":"yp1"},
  {"id":"en-mixed-y004","d":2,"q":"Why does the notice ask people to cancel if they cannot attend?","o":["To collect a cancellation fee","To stop all spectators from entering","To shorten the event for everyone","To free reserved places for others"],"a":3,"e":"公告末句說無法出席者應透過預約頁面取消，讓其他人使用空出的名額。文中沒有取消費、禁止旁觀者或縮短所有人活動時間的規定，因此釋出預約名額才符合取消的目的。","pid":"yp1"},
  {"id":"en-mixed-y005","d":3,"type":"multi","q":"Which statements are supported by the notice?（多選）","o":["A spectator may attend without a reservation.","Free admission means players do not need to book.","A reserved player place can be released if it is unclaimed at 2:10 p.m.","Players aged twelve to fifteen must book and attend with an adult.","A sixteen-year-old player does not need an accompanying adult."],"a":[0,2,3,4],"e":"(A) 正確：公告說旁觀者不需預約。(B) 錯誤：雖然入場免費，每位玩家仍須預約。(C) 正確：下午 2:10 尚未報到的玩家名額會釋出。(D) 正確：每位玩家都須預約，十二至十五歲玩家還須由成人陪同。(E) 正確：年滿十六歲可單獨參加，不須成人陪同。","pid":"yp1"},
  {"id":"en-mixed-y006","d":1,"q":"Which episode has the longest final audio?","o":["Lunch Memories","School Garden","Lost and Found","First Club Meeting"],"a":0,"e":"成品長度依序為 8、6、10、5 分鐘，Lunch Memories 最長。其他三集都未達十分鐘，不能把剪輯時間當成成品長度。","pid":"yp2","passages":{"yp2":"<b>Student Podcast Project: Editing Log</b><br>The following figures are fictional practice data from one project. Each episode was edited by a different student using the same editing software. Time includes editing only; it excludes recording and script writing.<br><br>Episode — Final audio length — Editing time — Number of speakers<br>School Garden — 8 minutes — 40 minutes — 2<br>Lost and Found — 6 minutes — 36 minutes — 3<br>Lunch Memories — 10 minutes — 50 minutes — 2<br>First Club Meeting — 5 minutes — 45 minutes — 4<br><br>The log records no information about sound quality or the editors' previous experience. All four episodes were completed and published on the school's internal website."}},
  {"id":"en-mixed-y007","d":2,"q":"How much editing time was recorded for the four episodes in total?","o":["121 minutes","29 minutes","171 minutes","161 minutes"],"a":2,"e":"剪輯時間相加：40＋36＋50＋45＝171 分鐘。121 漏加了 50，29 加總的是成品長度而非剪輯時間，161 則是加總錯誤。","pid":"yp2"},
  {"id":"en-mixed-y008","d":2,"q":"Which episode required the most editing time per minute of final audio?","o":["School Garden","Lost and Found","Lunch Memories","First Club Meeting"],"a":3,"e":"以剪輯時間除以成品長度，四集依序為 5、6、5、9 分鐘，First Club Meeting 最高。其餘三集都低於 9，不能只比較剪輯時間的絕對大小。","pid":"yp2"},
  {"id":"en-mixed-y009","d":3,"q":"Which conclusion cannot be established from this log?","o":["The four episodes were edited with the same software.","First Club Meeting has more speakers than School Garden.","Having more speakers causes an episode to require more editing time.","Script-writing time is excluded from the recorded editing time."],"a":2,"e":"紀錄未控制編輯經驗等變因，不能據此確定說話人數造成剪輯時間增加。相同軟體、四人比兩人多及不含寫稿時間則都是明載資訊。","pid":"yp2"},
  {"id":"en-mixed-y010","d":3,"type":"multi","q":"Which statements are supported by the editing log?（多選）","o":["Lunch Memories took fifty minutes to edit.","Lost and Found has fewer speakers than School Garden.","The editing times include script writing.","Each episode was edited by a different student.","The log shows that all four episodes have equally good sound."],"a":[0,3],"e":"(A) 正確：表中 Lunch Memories 的剪輯時間是五十分鐘。(B) 錯誤：Lost and Found 有三位說話者，比 School Garden 的兩位多。(C) 錯誤：紀錄明說剪輯時間不包括寫稿。(D) 正確：每集由不同學生剪輯。(E) 錯誤：紀錄沒有音質資料，不能判定四集音質一樣好。","pid":"yp2"},
  {"id":"en-mixed-y011","d":1,"q":"Which session requires a completed poster?","o":["Session A","Session D","Session B","Session C"],"a":1,"e":"Session D 的同儕回饋需攜帶已完成海報。A 與 B 為基礎課，C 要求電腦技能與筆電，均未要求已有成品。","pid":"yp3","passages":{"yp3":"<b>Poster Workshop: Booking Information</b><br>All sessions take place in Room 204. Materials are included. Participants must bring their own lunch if they stay for both morning and afternoon sessions.<br><br>Session A: Basic Lettering — Wednesday, 10:00 a.m.–noon — beginner level<br>Session B: Color and Contrast — Wednesday, 1:00–3:00 p.m. — beginner level<br>Session C: Digital Layout — Thursday, 10:00 a.m.–noon — requires basic computer skills and a laptop with a browser<br>Session D: Peer Review — Thursday, 1:00–3:00 p.m. — bring a completed poster, printed or digital<br><br>Book each session separately through the workshop page. There is no walk-in admission. To change a booking, cancel the original one and make a new reservation if a place is available.<br>Participants who cannot use the online form may phone the office for booking assistance. The office can help with reservations but cannot guarantee a place in a full session."}},
  {"id":"en-mixed-y012","d":1,"q":"Which plan is suitable for a beginner who is free only on Wednesday afternoon?","o":["Book Session B in advance.","Walk into Session A without booking.","Book Session C and attend on Wednesday.","Attend Session D without bringing a poster."],"a":0,"e":"B 是週三下午的初學課，且必須事先預約。A 時段不同且禁現場入場，C 在週四，D 也在週四並需帶海報。","pid":"yp3"},
  {"id":"en-mixed-y013","d":2,"q":"What must someone taking Sessions A and B provide for themselves?","o":["Lunch","Lettering materials","A completed poster","A laptop required for both sessions"],"a":0,"e":"同時參加上午和下午課需自備午餐，材料已含。完成海報僅 D 要求，筆電僅 C 要求，不能把其他課的條件套用到 A、B。","pid":"yp3"},
  {"id":"en-mixed-y014","d":3,"q":"What should a participant do to move from a booked session to another one?","o":["Keep the original booking and automatically receive a second place.","Cancel the original booking and reserve the new session if space remains.","Arrive at the new session without making a reservation.","Ask the office to guarantee a place even if the new session is full."],"a":1,"e":"公告明定先取消原預約，再依剩餘名額另行預約。沒有自動第二席，禁止未預約入場，辦公室也不保證已滿課程有位。","pid":"yp3"},
  {"id":"en-mixed-y015","d":2,"type":"multi","q":"Which statements agree with the booking information?（多選）","o":["Participants book sessions separately.","Session C requires a laptop but no basic computer skills.","Session D accepts only printed posters.","People unable to use the form can seek phone assistance.","Phone assistance guarantees entry to a full session."],"a":[0,3],"e":"(A) 正確：公告要求各場次分別預約。(B) 錯誤：C 場除了自備筆電，也要求基本電腦技能，並非不需技能。(C) 錯誤：D 場接受紙本或數位海報，並非只收紙本。(D) 正確：無法使用線上表單者可致電辦公室尋求預約協助。(E) 錯誤：辦公室明說不能保證已滿額場次有名額。","pid":"yp3"},
  {"id":"en-mixed-y016","d":1,"q":"What is the purpose of the requested descriptions?","o":["To approve new school clubs","To collect students' personal phone numbers","To introduce current school clubs","To choose one club photograph as a winner"],"a":2,"e":"編輯要介紹現有社團，末段明確排除新社申請。個人電話禁止列入，文章也未提攝影競賽。","pid":"yp4","passages":{"yp4":"<b>Message from the School Newsletter Editor</b><br>We are preparing an issue about school clubs. Please send a short description of your club's usual activities by Friday at 5:00 p.m. Include the club name, a contact person, and a meeting location.<br>Descriptions should be between 80 and 120 words. They may be shortened for space, but the contact details will be kept. Do not include members' personal phone numbers; use the club email address instead.<br>Photographs are optional. Before submitting one, obtain permission from every recognizable person in it. Send the photographer's name with the image so we can credit their work.<br>New clubs with no regular meeting location should write \"Contact us for the location.\" If your club has no email account yet, ask your teacher adviser to arrange a contact address before submitting.<br>The newsletter will describe current activities, not applications for new clubs. Submitting a description does not create or approve a club."}},
  {"id":"en-mixed-y017","d":2,"q":"What should a new club without a regular meeting place write?","o":["We meet in Room 204.","Leave the location field unexplained.","List every member's home address.","Contact us for the location."],"a":3,"e":"公告給出指定替代文字 Contact us for the location。204 並非此公告的場地，省略說明或列住址也不合指示。","pid":"yp4"},
  {"id":"en-mixed-y018","d":2,"q":"Which submission follows the editor's instructions?","o":["A 60-word text with club name, contact person, location, and members' phone numbers","A 150-word text with club name, location, and club email, but no contact person","A 100-word text with club name, contact person, location, club email, and no photo","A 100-word text with club details and a photo used without the recognizable students' permission"],"a":2,"e":"一百字在 80 至 120 字範圍內，且社團名、聯絡人、地點與信箱齊全；照片可不附。六十字不足且不得列私人電話，一百五十字超限且缺聯絡人，未經可辨識者同意的照片也不合規。","pid":"yp4"},
  {"id":"en-mixed-y019","d":3,"q":"Which inference is best supported by the message?","o":["Some wording in a club description may change before publication.","Every submitted photograph will definitely be printed.","An approved description automatically establishes a new club.","The editor may remove all contact details when shortening a text."],"a":0,"e":"為版面可縮短描述，因此文字可能調整。照片是否全刊未保證，提交不等於成立社團，聯絡資料則明說會保留。","pid":"yp4"},
  {"id":"en-mixed-y020","d":2,"type":"multi","q":"Which actions follow the message?（多選）","o":["Use a club email address rather than members' personal phone numbers.","Include the photographer's name with a submitted image.","Obtain permission only from the person standing in the center of a photograph.","Ask the teacher adviser for help arranging a contact address if the club has none.","Submit a new-club application instead of a description of current activities."],"a":[0,1,3],"e":"(A) 正確：編輯要求使用社團信箱，不能列出成員私人電話。(B) 正確：提交照片時須附攝影者姓名，方便標示作者。(C) 錯誤：照片中每位可辨識人物都須同意，並非只問站在中央的人。(D) 正確：社團尚無信箱時，須先請指導老師安排聯絡地址。(E) 錯誤：本期介紹現有活動，不受理新社團申請，兩者不能互相替代。","pid":"yp4"}
]);

TA.addQuestions('en-trans', [
  {"id":"en-trans-y001","d":1,"q":"Which sentence best translates 「記得在離開前鎖門。」?","o":["Remember locking the door before leaving.","Remember lock the door before leaving.","Remember to locking the door before leaving.","Remember to lock the door before leaving."],"a":3,"e":"remember to V 表示記得去做尚待完成的事，符合離開前鎖門的提醒。remember V-ing 表示記得曾做過；直接接 lock 或 to locking 均不合此句型。"},
  {"id":"en-trans-y002","d":1,"q":"Which sentence best translates 「她決定報名參加攝影課。」?","o":["She decided signing up for a photography class.","She decided to sign up for a photography class.","She decided sign up for a photography class.","She decided to signed up for a photography class."],"a":1,"e":"decide 後接 to V，且 sign up for 表報名。signing、直接接原形及 to 後接過去式 signed 都不合不定詞結構。"},
  {"id":"en-trans-y003","d":2,"q":"Which sentence best translates 「我很難在吵雜的房間裡專心。」?","o":["I have difficulty to concentrate in a noisy room.","I have difficulty concentrating in a noisy room.","I have difficult concentrating in a noisy room.","I am difficulty concentrating in a noisy room."],"a":1,"e":"have difficulty V-ing 表做某事有困難，用名詞 difficulty 與動名詞 concentrating。to concentrate 不合此搭配，difficult 是形容詞，am difficulty 則把名詞直接當表語而無正確結構。"},
  {"id":"en-trans-y004","d":2,"q":"Which sentence best translates 「這座橋使居民能更容易到達車站。」?","o":["The bridge enables residents reaching the station more easily.","The bridge enables residents reach the station more easily.","The bridge enables to residents to reach the station more easily.","The bridge enables residents to reach the station more easily."],"a":3,"e":"enable 人 to V 表使某人能做某事，因此用 enables residents to reach。受詞後不能在此改成 reaching 或原形 reach，enable 後的人也不需先加 to。"},
  {"id":"en-trans-y005","d":3,"q":"Which sentence best translates 「他堅持要為自己的錯誤負責。」?","o":["He insisted on taking responsibility for his own mistake.","He insisted to take responsibility for his own mistake.","He insisted on take responsibility for his own mistake.","He insisted on taking responsibility of his own mistake."],"a":0,"e":"insist on V-ing 表堅持做某事，take responsibility for 表為某事負責。insist 不在此接 to V，介系詞 on 後需動名詞，責任對象的介系詞則應為 for 而非 of。"},
  {"id":"en-trans-y006","d":1,"q":"Which sentence best translates 「我們把這個房間稱作閱讀角。」?","o":["We call this room as the reading corner.","We call this room for the reading corner.","We call this room the reading corner.","We call the reading corner to this room."],"a":2,"e":"call 加受詞加名詞補語可表示把某物稱作某名稱，不需介系詞。加 as 或 for 都不合此命名句型，最後一項則把受詞與名稱的關係及語序弄錯。"},
  {"id":"en-trans-y007","d":2,"q":"Which sentence best translates 「她告訴我該把箱子放在哪裡。」?","o":["She told me where putting the box.","She told me where put the box.","She told me where should I put the box.","She told me where to put the box."],"a":3,"e":"疑問詞 where 加 to V 可作 told 的受詞補充內容。where putting 及 where put 結構不完整；間接問句也不能使用 where should I 的直接問句語序。"},
  {"id":"en-trans-y008","d":3,"q":"Which revision corrects the subject error in \"After reading the instructions, the task seemed simpler to Mei\"?","o":["After read the instructions, the task seemed simpler to Mei.","After reading the instructions, the task was seemed simpler to Mei.","After reading the instructions, Mei found the task simpler.","After to read the instructions, the task seemed simpler to Mei."],"a":2,"e":"讀說明的人是 Mei，分詞結構的邏輯主詞需與主要子句主詞一致，故改以 Mei 為主詞。其餘仍讓 task 成為讀者，且分別另有 after 接 read、seem 誤用被動及 after to read 的結構錯誤。"},
  {"id":"en-trans-y009","d":1,"q":"Which sentence best translates 「請讓我知道你是否需要幫忙。」?","o":["Please let me to know whether you need help.","Please let me know whether you need help.","Please let me knowing whether you need help.","Please let me know whether do you need help."],"a":1,"e":"let 人加原形 know，後接 whether 引導的間接問句，語序為 you need。to know、knowing 都不合 let 的句型；whether do you need 則誤用問句倒裝。"},
  {"id":"en-trans-y010","d":2,"q":"Which sentence best translates 「儘管很疲倦，她仍完成了報告。」?","o":["Although she was tired, she finished the report.","Despite she was tired, she finished the report.","Although she was tired, but she finished the report.","Despite of being tired, she finished the report."],"a":0,"e":"Although 後可接完整子句，且主句不再加 but。Despite 後不能直接接 she was tired，despite of 也不是正確介系詞搭配；可改為 Despite being tired。"},
  {"id":"en-trans-y011","d":3,"q":"Which sentence best translates 「我原本希望能見到他，但他已經離開了。」?","o":["I had hoped to see him, but he had already left.","I had hoped seeing him, but he had already left.","I had hoped to saw him, but he had already left.","I had hoped see him, but he had already left."],"a":0,"e":"hope 後需接 to V，過去完成式 had hoped 在此表原先的希望，後句說他已離開。seeing、to saw 及直接接 see 都不合 hope 的不定詞補語結構。"},
  {"id":"en-trans-y012","d":2,"q":"Which sentence best translates 「如果沒有地圖，我們可能會迷路。」?","o":["Without a map, we might lost.","Without a map, we might get lost.","Without a map, we might getting lost.","Without a map, we might to get lost."],"a":1,"e":"might 後接原形 get，get lost 表迷路。lost 不能在此單獨接 might，getting 與 to get 也都不是情態助動詞後要求的原形。"},
  {"id":"en-trans-y013","d":1,"q":"Which sentence best translates 「我向他道歉，因為我打斷了他的話。」?","o":["I apologized him for interrupting him.","I apologized to him for interrupt him.","I apologized to him for interrupting him.","I apologized for him to interrupting him."],"a":2,"e":"apologize to 人 for V-ing 表因某行為向某人道歉。apologize 不直接接人作受詞，for 後需 interrupting，最後一項則將 to、for 的功能與位置倒置。"},
  {"id":"en-trans-y014","d":3,"q":"Which sentence best translates 「我們明天會請人修理這扇窗戶。」?","o":["We will have this window repairing tomorrow.","We will have this window repair tomorrow.","We will have repaired this window tomorrow.","We will have this window repaired tomorrow."],"a":3,"e":"have 加受詞加過去分詞表示請人完成某事，窗戶是被修理的，用 have this window repaired。repairing 與 repair 都未表達窗戶受動的關係；have repaired 則是未來完成式，沒有表達請人修理的使役意思。"},
  {"id":"en-trans-y015","d":2,"q":"Which sentence best translates 「這是我第一次獨自搭火車旅行。」?","o":["This is the first time I have travel alone by train.","This is the first time I has traveled alone by train.","This is the first time I have traveled alone by train.","This is the first time I have traveling alone by train."],"a":2,"e":"This is the first time 後可用現在完成式，I 搭配 have traveled。have travel 缺過去分詞，has 不配合 I，have traveling 則不是完成式的正確形式。"},
  {"id":"en-trans-y016","d":2,"q":"Which sentence best translates 「這個消息讓所有隊員都感到興奮。」?","o":["The news made all the team members excited.","The news made all the team members exciting.","The news made all the team members to be excited.","The news made all the team members excite."],"a":0,"e":"make 加受詞加形容詞可表使人處於某狀態，隊員感到興奮用 excited。exciting 表令人興奮，make 的使役補語不用 to be，excite 則把隊員改成主動使人興奮的行動者。"},
  {"id":"en-trans-y017","d":3,"q":"Which sentence combines \"The path is narrow\" and \"The path leads to the old tower\" into one grammatical sentence?","o":["The path is narrow leads to the old tower.","The path leading to the old tower it is narrow.","The narrow path lead to the old tower.","The narrow path leads to the old tower."],"a":3,"e":"把 narrow 作形容詞修飾 path，句子保留單一主要動詞 leads，結構完整。第一干擾項直接堆疊 is 與 leads，第二重複主詞 path 與 it，第三未使動詞配合單數 path。"}
]);
